import sys, json, time, platform, statistics as stats, random
from pathlib import Path

START = time.time()
sys.path.append('storage/shared')

# Seed utilities (package or shim)
seed_tools_ok = True
try:
    from utilities.seed_tools import set_seed, make_rng, seed_from_str, mix_seed
except Exception:
    seed_tools_ok = False
    try:
        from seed_tools import set_seed, make_rng, seed_from_str, mix_seed
    except Exception:
        import random as _r, hashlib as _h
        def _u32(x): return int(x) & 0xFFFFFFFF
        def set_seed(s): _r.seed(_u32(s)); return _u32(s)
        def make_rng(s): set_seed(s); return None, _r.Random(_u32(s))
        def seed_from_str(s): return int(_h.sha256(s.encode()).hexdigest()[:8], 16)
        def mix_seed(a,b): return (_u32(a) ^ (_u32(b) + 0x9E3779B9)) & 0xFFFFFFFF

from coord.buffered_ring import simulate_buffered_ring

base_seed = seed_from_str("Axiom-buffered-ring-v0")
set_seed(base_seed)
_, _ = make_rng(base_seed)

cfg = {
    "N": 24,
    "max_steps": 500,
    "p_values": [1.0, 0.8],
    "reliability": 1.0,
    "buffer_sizes": [4, 8],
    "service_rates": [1, 2, 4],
    "modes": ["uni", "bidir"],
    "replicates": 15
}

results = []
for mode in cfg["modes"]:
    for p in cfg["p_values"]:
        for B in cfg["buffer_sizes"]:
            for mu in cfg["service_rates"]:
                run_metrics = []
                drops_per_step = []
                processed_per_step = []
                queue_peaks = []
                succ = 0
                for k in range(cfg["replicates"]):
                    run_seed = mix_seed(base_seed, hash((mode, p, B, mu, k)) & 0xFFFFFFFF)
                    rng = random.Random(run_seed)
                    res = simulate_buffered_ring(
                        N=cfg["N"],
                        p_send=p,
                        reliability=cfg["reliability"],
                        bidirectional=(mode == "bidir"),
                        buffer_size=B,
                        service_rate=mu,
                        max_steps=cfg["max_steps"],
                        rng=rng,
                        track_history=True,
                    )
                    # Basic metrics
                    steps = res["steps"]
                    t_full = res["steps_to_full"]
                    cov = 1.0 if t_full is not None else (res["final_informed"] / cfg["N"])
                    thr = res["messages_attempted"] / max(1, steps)
                    run_metrics.append({"coverage": cov, "time_to_full": t_full, "throughput_msgs_per_step": thr})
                    if t_full is not None:
                        succ += 1
                    # Aux metrics
                    drops_per_step.append(res["dropped"] / max(1, steps))
                    processed_per_step.append(res["processed"] / max(1, steps))
                    queue_peaks.append(res["queue_peak"])
                # Aggregate
                def vals(key):
                    v = [m.get(key) for m in run_metrics if m.get(key) is not None]
                    return v
                agg = {}
                for key in ["coverage", "time_to_full", "throughput_msgs_per_step"]:
                    v = vals(key)
                    if v:
                        try:
                            agg[key] = {"count": len(v), "mean": float(stats.fmean(v)), "min": float(min(v)), "max": float(max(v))}
                        except Exception:
                            v2 = [x for x in v if x is not None]
                            agg[key] = {"count": len(v2), "mean": float(stats.fmean(v2)) if v2 else None, "min": float(min(v2)) if v2 else None, "max": float(max(v2)) if v2 else None}
                    else:
                        agg[key] = {"count": 0}
                agg["success_rate"] = succ / cfg["replicates"]
                agg["drops_per_step_mean"] = float(stats.fmean(drops_per_step)) if drops_per_step else None
                agg["processed_per_step_mean"] = float(stats.fmean(processed_per_step)) if processed_per_step else None
                agg["queue_peak_mean"] = float(stats.fmean(queue_peaks)) if queue_peaks else None
                results.append({
                    "mode": mode, "p_send": p, "buffer_size": B, "service_rate": mu,
                    "replicates": cfg["replicates"], "aggregate": agg
                })

out_dir = Path("storage/shared/coord/results")
out_dir.mkdir(parents=True, exist_ok=True)
out_path = out_dir / "axiom_buffered_ring_v0.json"

report = {
    "env": {
        "python": platform.python_version(),
        "implementation": platform.python_implementation(),
        "platform": platform.platform(),
        "seed_tools_imported": seed_tools_ok,
    },
    "config": cfg,
    "grid_results": results,
}

with open(out_path, "w", encoding="utf-8") as f:
    json.dump(report, f, indent=2, sort_keys=True)

END = time.time()
# Print compact highlights: compare uni vs bidir at p=0.8, B=8 across mu
def pick(mode, p, B):
    rows = [r for r in results if r["mode"] == mode and r["p_send"] == p and r["buffer_size"] == B]
    return {r["service_rate"]: r["aggregate"] for r in rows}
highlights = {"uni": pick("uni", 0.8, 8), "bidir": pick("bidir", 0.8, 8)}
print("=== Bounded Buffers Ring v0 ===")
print(json.dumps({
    "artifact": str(out_path),
    "highlights_p0.8_B8": highlights,
    "timing_sec": round(END - START, 6),
}, indent=2))
print("Buffered baseline complete.")

